        $errorsList = new ConstraintFailList();
        $candidate = self::tryFrom($value, $errorsList);
        if ($errorsList->hasErrors()) {
            throw $errorsList->asConstraintException();
        }
        \assert($candidate instanceof UserInvitationStatusVO);
        return $candidate;
    }
    public static function empty(): UserInvitationStatusVO
    {
        return new UserInvitationStatusVO(null);
    }
    public static function from(UserInvitationStatusVO|UserInvitationStatusOptions|null $value): UserInvitationStatusVO
    {
        return self::fromUnsafe($value);
    }
    public static function tryFrom(mixed $value, ConstraintFailList $list): ?UserInvitationStatusVO
    {
        if ($value instanceof UserInvitationStatusVO) {
            // If is a ValueObject, its already validated... nothing to append
            return $value;
        } elseif (!$value) {
            return new UserInvitationStatusVO($value);
        } elseif (is_string($value)) {
            if ($typed = self::readFromString($value)) {
                return self::tryFrom($typed, $list);
            } else {
                $list->add(new ConstraintFail('wrong_format', ['status'], [$value], ['UserInvitationStatusOptions']));
                return null;
            }
        } elseif (is_a($value, UserInvitationStatusOptions::class)) {
            return new UserInvitationStatusVO($value);
        } else {
            $list->add(new ConstraintFail('wrong_type', ['status'], [$value], ['UserInvitationStatusOptions']));
            return null;
        }
    }
    private static function readFromString(string $enumString): ?UserInvitationStatusOptions
    {
        if (in_array($enumString, ['pENDING', 'pending', 'PENDING'])) {
            return UserInvitationStatusOptions::PENDING;
        }
        if (in_array($enumString, ['ACCEPTED', 'accepted', 'aCCEPTED'])) {
            return UserInvitationStatusOptions::ACCEPTED;
        }
        if (in_array($enumString, ['CANCELLED', 'cancelled', 'cANCELLED'])) {
            return UserInvitationStatusOptions::CANCELLED;
        }
        if (in_array($enumString, ['expired', 'EXPIRED', 'eXPIRED'])) {
            return UserInvitationStatusOptions::EXPIRED;
        }
        return null;
    }
    private static function fromUnsafe(mixed $value): UserInvitationStatusVO
    {
